def unique_paths_iii(grid):
    rows, cols = len(grid), len(grid[0])
    start = None
    empty_count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                start = (r, c)
            if grid[r][c] == 0:
                empty_count += 1

    count = 0

    def backtrack(r, c, visited):
        nonlocal count
        if grid[r][c] == 2:
            if visited == empty_count:
                count += 1
            return
        original = grid[r][c]
        grid[r][c] = -1
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != -1:
                backtrack(nr, nc, visited + (1 if grid[nr][nc] == 0 else 0))
        grid[r][c] = original

    backtrack(start[0], start[1], 0)
    return count

